function updateOverrideReason() {
	// g_form.addInfoMessage("updateOverrideReason()");
    var finalEsi = g_form.getValue('final_esi');
    var suggested = g_form.getValue('suggested_esi');
    var differs = finalEsi !== '' && finalEsi !== suggested;

    g_form.setDisplay('override_reason', differs);
    g_form.setMandatory('override_reason', differs);
    if (!differs) g_form.clearValue('override_reason');
}

function setSuggestionClone() {
	setTimeout(function() {
		var choiceValue = g_form.getValue('suggested_esi');
		var optionObj = g_form.getOption('suggested_esi', choiceValue);
		if(optionObj && optionObj.text)
		{
			var displayValue = optionObj.text;
			g_form.setValue('suggested', displayValue);
		}
		else
		{
			g_form.setValue('suggested', choiceValue);
		}
	}, 100);
}

function readOnlyFields() {
	// g_form.addInfoMessage("readOnlyFields()");
    g_form.setReadOnly('patient', true);
    g_form.setReadOnly('encounter', true);
}

